graph = {"A": ["B", "C"], "B": ["A", "D"], "C": ["A", "D"], "D": ["B", "C"]}
visited = ["A"]
queue = ["A"]
while queue:
    v = queue.pop(0)
    for n in graph[v]:
        if n not in visited:
            visited.append(n)
            queue.append(n)
print(visited)

